// ─── File: StatusDemo.java ───
// This file contains multiple top-level classes for a runnable demo.
// In a real project each class would live in its own file.
package com.bank.status;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StatusDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        // Clean formatter so demo output reads like real banking logs.
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"), AccountStatus.ACTIVE);
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"),  AccountStatus.FROZEN);

        WithdrawalService service = new WithdrawalService();

        // Rajesh is ACTIVE → withdrawal allowed.
        service.withdraw(rajesh, new BigDecimal("50000"));
        // Priya is FROZEN → withdrawal blocked by the enum rule.
        service.withdraw(priya, new BigDecimal("10000"));

        log.info(() -> "Total declared statuses: " + AccountStatus.values().length);
        // Safe reference comparison because each constant is a singleton.
        log.info(() -> "Is priya frozen? " + (priya.getStatus() == AccountStatus.FROZEN));
    }
}

// ─── Would be in AccountStatus.java in a real project ───
enum AccountStatus {
    ACTIVE("Active account", true),
    FROZEN("Frozen by compliance", false),
    CLOSED("Closed permanently", false);

    private final String label;          // extra data carried by each constant
    private final boolean withdrawAllowed;

    // Enum constructor is implicitly private; called once per constant.
    AccountStatus(String label, boolean withdrawAllowed) {
        this.label = label;
        this.withdrawAllowed = withdrawAllowed;
    }

    public String label() { return label; }
    public boolean canWithdraw() { return withdrawAllowed; }
}

// ─── Would be in Account.java in a real project ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private AccountStatus status;

    Account(String accountId, String holderName, BigDecimal balance, AccountStatus status) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        this.status = status;
    }

    void debit(BigDecimal amount)  { this.balance = this.balance.subtract(amount); }
    void credit(BigDecimal amount) { this.balance = this.balance.add(amount); }

    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    AccountStatus getStatus() { return status; }
}

// ─── Would be in WithdrawalService.java in a real project ───
class WithdrawalService {
    private static final Logger log = Logger.getLogger("BankLog");

    void withdraw(Account account, BigDecimal amount) {
        // The rule lives inside the enum, not scattered across if-statements.
        if (!account.getStatus().canWithdraw()) {
            log.warning(() -> "BLOCKED: " + account.getHolderName()
                    + " account " + account.getAccountId()
                    + " is " + account.getStatus().label());
            return;
        }
        if (account.getBalance().compareTo(amount) < 0) {
            log.severe(() -> "FAILED: insufficient funds for " + account.getHolderName());
            return;
        }
        account.debit(amount);
        log.info(() -> "SUCCESS: " + account.getHolderName() + " withdrew Rs." + amount
                + ", new balance Rs." + account.getBalance());
    }
}
